*{box-sizing:border-box} :root{--ink:#e7e2d4;--muted:#a19f90;--gold:#d8b979;--dark:#101510;--panel:rgba(20,25,20,.88);--accent:#f09a52}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101510;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}#app{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#101510}#world{display:block;width:100%;height:100%;background:#151c18;image-rendering:pixelated}.vignette,.grain{position:absolute;inset:0;pointer-events:none}.vignette{z-index:2;background:radial-gradient(ellipse at 50% 46%,transparent 35%,rgba(5,9,7,.2) 72%,rgba(4,7,5,.82) 100%)}.grain{z-index:3;opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.92' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.24'/%3E%3C/svg%3E")}.screen{position:absolute;inset:0;z-index:5;overflow:auto;background:radial-gradient(ellipse at 49% 45%,rgba(34,52,40,.75),rgba(12,17,14,.91) 56%,rgba(8,12,10,.98) 100%)}.screen:before{content:"";position:absolute;inset:0;pointer-events:none;opacity:.3;background:linear-gradient(90deg,transparent 49.9%,rgba(202,180,132,.12) 50%,transparent 50.1%),linear-gradient(0deg,transparent 49.9%,rgba(202,180,132,.1) 50%,transparent 50.1%);mask-image:radial-gradient(ellipse,black,transparent 70%)}.topbar{height:92px;margin:0 6.4%;display:flex;align-items:center;border-bottom:1px solid rgba(220,205,163,.16);position:relative;z-index:1}.brand-mark{width:37px;height:37px;border:1px solid rgba(216,185,121,.7);border-radius:50%;display:grid;place-items:center;color:var(--gold);font-size:20px;margin-right:13px;text-shadow:0 0 14px #dfb55d}.brand{font-family:Cinzel,serif;letter-spacing:2px;font-size:15px;font-weight:700}.brand span{display:block;font:500 8px 'DM Sans',sans-serif;letter-spacing:2.2px;color:#97978a;margin-top:3px}.run-stamp{margin-left:auto;font-size:9px;letter-spacing:2px;color:#9f9e90}.run-stamp i{font-style:normal;color:var(--gold);font-size:15px;margin-left:10px}.hero-copy{position:relative;z-index:1;margin:55px 0 32px 12.5%;}.eyebrow,.section-label,.modal-kicker{font-size:10px;letter-spacing:2.7px;color:var(--gold);font-weight:600}.eyebrow{display:flex;align-items:center;gap:10px;margin:0 0 17px}.eyebrow span{height:1px;width:26px;background:var(--gold)}h1,h2{font-family:Cinzel,serif;font-weight:500;line-height:1.04;letter-spacing:-.7px;margin:0}h1{font-size:clamp(38px,5vw,63px)}h1 em,h2 em{font-weight:400;color:#d9bd83}.intro{font-size:13px;line-height:1.8;color:#aaa99b;margin:18px 0 0;letter-spacing:.15px}.selection-wrap{position:relative;z-index:1;width:min(760px,75%);margin:0 auto 75px}.section-label{height:28px;display:flex;justify-content:space-between;border-bottom:1px solid rgba(221,203,159,.17);color:#b6ad92;font-size:9px}.section-label i{font-style:normal;color:#797d70;font-size:9px;letter-spacing:1px}.class-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding-top:13px}.class-card{height:148px;padding:14px 14px 12px;position:relative;background:linear-gradient(145deg,rgba(43,54,44,.68),rgba(17,23,19,.78));border:1px solid rgba(204,200,172,.15);cursor:pointer;transition:.2s;overflow:hidden;text-align:left}.class-card:after{content:"";position:absolute;inset:auto 0 0;height:2px;background:var(--class-color);opacity:.2;transition:.2s}.class-card:hover,.class-card.selected{border-color:color-mix(in srgb,var(--class-color),transparent 40%);background:linear-gradient(145deg,rgba(53,66,50,.92),rgba(19,26,21,.94));transform:translateY(-2px)}.class-card.selected:after{opacity:1;box-shadow:0 0 16px var(--class-color)}.class-symbol{font-size:22px;color:var(--class-color);text-shadow:0 0 18px var(--class-color);display:block;height:35px}.class-number{position:absolute;right:13px;top:15px;color:#757b6d;font-size:9px;letter-spacing:1px}.class-card h3{font:600 12px Cinzel,serif;letter-spacing:.6px;margin:0 0 6px;color:#e5e0d1}.class-card p{margin:0;color:#96988b;font-size:9px;line-height:1.5}.class-tag{position:absolute;bottom:10px;right:12px;color:var(--class-color);font-size:7px;letter-spacing:1px;text-transform:uppercase;opacity:.85}.selection-footer{display:flex;align-items:center;justify-content:space-between;padding-top:17px}.persist-info{display:flex;align-items:center;gap:9px;color:#98988b;font-size:10px}.tiny-sigil{color:var(--gold);font-size:16px}.primary-button{background:#d2b778;border:1px solid #e6ca8b;color:#1b2019;height:43px;padding:0 21px;min-width:203px;letter-spacing:1.5px;font-weight:700;font-size:10px;cursor:pointer;transition:.2s;display:flex;align-items:center;justify-content:space-between;gap:25px}.primary-button:hover{background:#f0d397;box-shadow:0 4px 25px rgba(209,171,94,.22);transform:translateY(-1px)}.primary-button b{font-size:16px;font-weight:400}.title-bottom{position:absolute;bottom:17px;left:6.4%;right:6.4%;display:flex;justify-content:space-between;color:#737b70;font-size:8px;letter-spacing:1.4px}.title-bottom b{color:#c3ad79;margin:0 6px;font-weight:400}.hidden{display:none!important}
/* in-run HUD */
#hud{position:absolute;inset:0;z-index:4;pointer-events:none}.hud-top{position:absolute;left:4.5%;right:4.5%;top:24px;display:flex;align-items:flex-start;justify-content:space-between;text-shadow:0 2px 6px #000}.run-info{display:flex;align-items:center;gap:10px}.mini-brand{height:37px;width:37px;display:grid;place-items:center;border:1px solid rgba(221,188,119,.7);border-radius:50%;color:var(--gold);font-size:19px}.run-info strong{display:block;font:700 12px Cinzel,serif;letter-spacing:1.6px}.run-info small{display:block;color:#b8b2a1;font-size:8px;letter-spacing:1.7px;margin-top:4px}.wave-info{text-align:center;width:180px}.wave-info small,.run-clock small{display:block;color:#c1b895;font-size:8px;letter-spacing:2px}.wave-info strong{display:block;font:600 18px Cinzel,serif;letter-spacing:1px;margin-top:3px}.wave-info i{font-style:normal;color:#8d8c7c}.wave-info strong span:last-child{color:#aaa999}.wave-track{height:2px;background:rgba(220,213,181,.26);margin-top:8px}.wave-track span{height:100%;display:block;width:0;background:#d7b76d;transition:width .25s}.run-clock{display:grid;grid-template-columns:auto auto;column-gap:7px;align-items:center;text-align:right;font-size:14px;font-variant-numeric:tabular-nums}.run-clock small{grid-column:2;font-size:7px;margin-top:2px}.clock-dot{width:6px;height:6px;border-radius:50%;background:#d7b76d;box-shadow:0 0 9px #dfbd70}.objective{position:absolute;top:107px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;padding:8px 14px;background:rgba(12,16,13,.44);border:1px solid rgba(227,208,156,.12);min-width:235px;justify-content:center}.obj-icon{color:#dec583;font-size:16px}.objective b{display:block;text-align:left;font-size:9px;letter-spacing:1.5px;font-weight:600}.objective small{display:block;color:#a9a797;font-size:9px;margin-top:3px}.crosshair{position:absolute;left:50%;top:50%;width:21px;height:21px;transform:translate(-50%,-50%);opacity:.85}.crosshair i{position:absolute;background:rgba(240,232,204,.88);width:1px;height:5px}.crosshair i:nth-child(1){top:0;left:10px}.crosshair i:nth-child(2){bottom:0;left:10px}.crosshair i:nth-child(3){left:0;top:8px;width:5px;height:1px}.crosshair i:nth-child(4){right:0;top:8px;width:5px;height:1px}.crosshair b{position:absolute;left:9px;top:8px;width:3px;height:3px;border:1px solid #f4dda6;border-radius:50%}.hit-marker{position:absolute;top:calc(50% - 23px);left:calc(50% + 15px);color:#fff3ce;font-size:19px;opacity:0;text-shadow:0 0 10px #ffae57}.bottom-hud{position:absolute;left:5%;right:5%;bottom:27px;display:grid;grid-template-columns:190px 1fr 142px;align-items:end;gap:25px;text-shadow:0 2px 6px #000}.vitals{padding:10px 12px;background:linear-gradient(90deg,rgba(12,16,13,.76),rgba(12,16,13,.35));border-left:2px solid rgba(230,197,122,.8)}.vital-head,.vital-foot{display:flex;justify-content:space-between;align-items:center}.vital-head{font-size:8px;letter-spacing:1.5px;color:#c2bda9}.vital-head b{font:600 10px 'DM Sans',sans-serif;color:#f0e8d5;letter-spacing:.4px}.vital-head i{font-style:normal;color:#8f8b7b}.bar{height:5px;background:rgba(210,205,180,.2);margin:8px 0 7px}.bar span{display:block;width:100%;height:100%;background:linear-gradient(90deg,#d9b765,#f2d394);box-shadow:0 0 8px rgba(235,202,130,.4);transition:width .25s}.vital-foot{color:#a7a391;font-size:7px;letter-spacing:1px}.vital-foot b{color:#e4d8b5;font-size:9px;margin-left:3px}.ability-row{display:flex;justify-content:center;gap:8px}.ability{height:51px;min-width:138px;position:relative;overflow:hidden;display:flex;align-items:center;padding:0 9px;gap:8px;background:rgba(12,16,13,.76);border:1px solid rgba(222,212,182,.18)}.ability.weapon{min-width:158px}.ability-key{width:25px;height:25px;border:1px solid rgba(214,198,154,.35);display:grid;place-items:center;color:#e1d5b2;font-size:8px}.ability-glyph{font-size:18px;color:#e0bb70;text-shadow:0 0 12px currentColor}.ability-label{white-space:nowrap}.ability-label b{display:block;font-size:8px;letter-spacing:.8px}.ability-label small{display:block;color:#9d9b8c;font-size:7px;letter-spacing:1px;margin-top:4px}.cooldown-shade{position:absolute;inset:0 100% 0 0;background:rgba(5,7,6,.63);transition:inset .12s}.score-panel{display:flex;justify-content:space-between;gap:15px}.score-panel div{display:flex;flex-direction:column;align-items:flex-end}.score-panel small{font-size:7px;color:#b6b19f;letter-spacing:1.3px}.score-panel b{font:500 19px Cinzel,serif;color:#f1dfb5}.combo-wrap{border-left:1px solid rgba(221,201,155,.25);padding-left:12px}.combo-wrap b{font-size:14px}.minimap{position:absolute;top:118px;right:4.5%;height:93px;width:93px;border:1px solid rgba(222,203,153,.28);background:rgba(11,15,12,.65);padding:3px;opacity:.8}.minimap canvas{width:100%;height:100%}.wave-banner{position:absolute;top:36%;left:50%;transform:translate(-50%,-50%);text-align:center;opacity:0;transition:.35s;pointer-events:none;text-shadow:0 2px 8px #000}.wave-banner.show{opacity:1;transform:translate(-50%,-50%) scale(1.05)}.wave-banner span{display:block;font-size:9px;color:#d8be82;letter-spacing:4px}.wave-banner b{font:500 25px Cinzel,serif;letter-spacing:3px}.toast{position:absolute;top:22%;left:50%;transform:translate(-50%,-50%);padding:9px 16px;background:rgba(12,15,13,.82);border:1px solid rgba(221,199,147,.35);font-size:10px;letter-spacing:1px;opacity:0;transition:opacity .2s}.toast.show{opacity:1}.damage-flash,#damage-flash{position:absolute;inset:0;z-index:4;pointer-events:none;background:radial-gradient(ellipse,transparent 35%,rgba(212,39,28,.48));opacity:0;transition:opacity .2s}.touch-controls{display:none}.modal-screen{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:35px 20px}.modal-kicker{margin-bottom:18px}h2{font-size:clamp(36px,4.5vw,55px)}.modal-intro{font-size:13px;color:#a7a698;margin:13px 0 28px}.upgrade-cards{display:grid;grid-template-columns:repeat(3,minmax(170px,220px));gap:13px}.upgrade-card{background:linear-gradient(145deg,rgba(49,60,48,.85),rgba(18,24,20,.94));border:1px solid rgba(221,204,161,.24);padding:20px 17px;text-align:left;min-height:180px;cursor:pointer;position:relative;transition:.2s}.upgrade-card:hover{transform:translateY(-4px);border-color:#d6b66e;box-shadow:0 12px 30px rgba(0,0,0,.25)}.upgrade-card .upgrade-icon{font-size:26px;color:#dfbd75;display:block;margin-bottom:12px}.upgrade-card h3{font:600 14px Cinzel,serif;margin:0 0 8px}.upgrade-card p{font-size:11px;color:#a8a899;line-height:1.65;margin:0}.upgrade-card span.pick{position:absolute;bottom:13px;right:14px;color:#d8bb7e;font-size:8px;letter-spacing:1.5px}.modal-foot{width:min(670px,90%);display:flex;justify-content:space-between;color:#868779;font-size:8px;letter-spacing:1.6px;margin-top:30px}.modal-foot b{color:#d8b979;margin-left:7px}.run-summary{display:flex;gap:0;border-top:1px solid rgba(220,201,158,.2);border-bottom:1px solid rgba(220,201,158,.2);margin:7px 0 22px}.run-summary div{padding:17px 26px;min-width:120px;border-right:1px solid rgba(220,201,158,.15)}.run-summary div:last-child{border:0}.run-summary small,.legacy-card small{display:block;color:#9c9b8d;font-size:8px;letter-spacing:1.5px}.run-summary b{display:block;font:500 22px Cinzel,serif;color:#e4d4ab;margin-top:6px}.legacy-card{display:flex;align-items:center;gap:13px;padding:13px 17px;margin-bottom:22px;background:rgba(194,157,86,.1);border:1px solid rgba(216,185,121,.23);min-width:360px;text-align:left}.legacy-sigil{font-size:25px;color:#dec17d}.legacy-card b{display:block;font:600 17px Cinzel,serif;margin-top:2px;color:#ebd5a5}.legacy-card p{margin:0 0 0 auto;color:#a7a595;font-size:9px;max-width:145px;line-height:1.45}.pause-overlay{position:absolute;z-index:8;inset:0;background:rgba(10,14,11,.86);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.pause-overlay h2{margin-bottom:9px}.pause-overlay p{color:#aaa99b;font-size:12px;margin:0 0 23px}.pause-overlay .primary-button{justify-content:center}
