%;border:1px solid rgba(236,218,170,.34);background:rgba(20,24,20,.28);touch-action:none}.joy i{position:absolute;inset:20px;border-radius:50%;border:1px solid rgba(236,218,170,.2)}.joy b{position:absolute;width:34px;height:34px;left:32px;top:32px;border-radius:50%;background:rgba(217,185,121,.55);border:1px solid rgba(255,235,185,.65)}#touch-fire,#touch-ability,#touch-dash{pointer-events:auto;position:absolute;border-radius:50%;border:1px solid rgba(238,212,157,.6);background:rgba(20,24,20,.64);color:#e4c57e;touch-action:none}#touch-fire{width:68px;height:68px;right:20px;bottom:111px;font-size:26px}#touch-ability{width:48px;height:48px;right:93px;bottom:168px;font-size:14px}#touch-dash{width:42px;height:42px;right:99px;bottom:100px;font-size:17px}.run-summary div{min-width:70px;padding:13px 8px}.run-summary small{font-size:6px;letter-spacing:.8px}.run-summary b{font-size:18px}.legacy-card{min-width:0;width:min(360px,92vw)}.legacy-card p{font-size:8px}.upgrade-cards{grid-template-columns:repeat(3,minmax(92px,1fr));gap:6px;width:100%}.upgrade-card{min-height:166px;padding:13px 10px}.upgrade-card h3{font-size:10px}.upgrade-card p{font-size:9px}.upgrade-card .upgrade-icon{font-size:21px;margin-bottom:9px}.upgrade-card span.pick{font-size:6px;right:8px}.modal-intro{font-size:11px;margin:10px 0 20px}.modal-foot{font-size:6px}.modal-kicker{font-size:8px}h2{font-size:39px}}
@media(max-height:700px) and (min-width:701px){.hero-copy{margin-top:30px;margin-bottom:20px}h1{font-size:48px}.class-card{height:128px}.selection-wrap{margin-bottom:50px}.title-bottom{bottom:10px}}

