 {id:'ember',name:'Ember Warden',title:'Keeper of the First Flame',symbol:'♨',tag:'FLAME · RADIANCE',color:'#f29a56',desc:'A lantern against the long night. Burn through the dark.',weapon:'FIRE · 0.4S',sigil:'CINDER RING',damage:26,rate:.38,speed:1,ability:'ring'},
