let profile=loadProfile(),selected=0,state='menu',last=performance.now(),dt=0,keys={},mouseDown=false,locked=false,run=null,worldSeed=1,screenW=0,screenH=0,dpr=1,toastTimer=0,bannerTimer=0,fireTimer=0,abilityTimer=0,dashTimer=0,player={x:7.5,y:7.5,angle:0},entities=[],effects=[],depthBuffer=[], map=[], mapN=17, spawnTimer=0, waveStart=0, frame=0,joystick={x:0,y:0,active:false,pointer:null},touchFire=false;
function loadProfile(){try{return Object.assign({shards:0,legacy:0,runs:0,bestWave:0},JSON.parse(localStorage.getItem('veilfall-profile')||'{}'))}catch{return {shards:0,legacy:0,runs:0,bestWave:0}}}
