 const c=classes[selected];run={cls:c,wave:1,maxWaves:6,health:100+profile.legacy*3,maxHealth:100+profile.legacy*3,ward:0,damage:c.damage*(1+profile.legacy*.02),rate:c.rate,speed:c.speed,abilityRate:1,soulHeal:0,kills:0,streak:1,bestStreak:1,start:performance.now(),elapsed:0,shots:0,cleared:0,upgrades:[],waveKills:0,waveTarget:0,finished:false};
