function createArena(){mapN=17;map=Array.from({length:mapN},(_,y)=>Array.from({length:mapN},(_,x)=>(x===0||y===0||x===mapN-1||y===mapN-1)?1:0));
 // broken pillars and ribs create lines of sight, but keep a clear central arena
