function resumeRun(){if(state!=='paused')return;state='playing';$('pause-overlay').classList.add('hidden');if(innerWidth>750)canvas.requestPointerLock?.();last=performance.now()}
function endRun(won){if(state!=='playing')return;state='ended';run.finished=true;document.exitPointerLock?.();const waves=won?run.maxWaves:run.wave-1,shards=Math.max(1,waves*2+Math.floor(run.kills/8)+(won?8:0));profile.shards+=shards;profile.runs++;profile.bestWave=Math.max(profile.bestWave,waves);saveProfile();$('end-kicker').textContent=won?'THE VEIL REMEMBERS':'THE VEIL CLOSES';$('end-title').innerHTML=won?'The dark <em>recedes.</em>':'The dark <em>endures.</em>';$('end-copy').textContent=won?'You held the line. Your legend carries forward.':'Even in defeat, your courage leaves a mark.';$('summary-waves').textContent=`${waves} / ${run.maxWaves}`;$('summary-kills').textContent=run.kills;$('summary-time').textContent=formatTime(run.elapsed);$('summary-shards').textContent=`+${shards}`;$('legacy-total').textContent=profile.shards;$('legacy-message').textContent=`Forge a permanent blessing for 3 shards. Rank ${profile.legacy} · +${profile.legacy*2}% spell power.`;$('end-screen').classList.remove('hidden');$('hud').classList.add('hidden')}
function formatTime(seconds){const m=Math.floor(seconds/60),s=Math.floor(seconds%60);return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function chooseUpgrade(index){const choice=run.currentChoices[index];choice.apply(run);run.upgrades.push(choice.id);$('upgrade-screen').classList.add('hidden');$('hud').classList.remove('hidden');state='playing';run.wave++;if(run.wave>run.maxWaves){endRun(true);return}beginWave();showBanner(`WAVE ${['I','II','III','IV','V','VI'][run.wave-1]}`,['THE VEIL STIRS','ASHES IN THE WIND','WHISPERS BELOW','STORM WITHOUT END','THE LONG NIGHT','THE VEIL LORD'][run.wave-1]);last=performance.now()}
function openUpgrade(){state='upgrade';$('hud').classList.add('hidden');const pool=upgrades.slice().sort(()=>Math.random()-.5).slice(0,3);run.currentChoices=pool;const wrap=$('upgrade-cards');wrap.innerHTML='';pool.forEach((u,i)=>{const card=document.createElement('button');card.className='upgrade-card';card.innerHTML=`<span class="upgrade-icon">${u.icon}</span><h3>${u.name}</h3><p>${u.text}</p><span class="pick">CHOOSE →</span>`;card.onclick=()=>chooseUpgrade(i);wrap.append(card)});$('upgrade-screen').classList.remove('hidden')}

