function isWall(x,y){const gx=Math.floor(x),gy=Math.floor(y);return !map[gy]||map[gy][gx]!==0}
function canStand(x,y,r=.22){return !isWall(x-r,y-r)&&!isWall(x+r,y-r)&&!isWall(x-r,y+r)&&!isWall(x+r,y+r)}
function spawnEnemy(boss=false){let p=null;for(let i=0;i<80;i++){const a=Math.random()*TAU,d=5+Math.random()*4,x=player.x+Math.cos(a)*d,y=player.y+Math.sin(a)*d;if(canStand(x,y,.3)&&Math.hypot(x-player.x,y-player.y)>4){p={x,y};break}}if(!p)p={x:14.5,y:14.5};const wave=run.wave;const kind=boss?'warden':Math.random()<(wave>=3?.28:.12)?'ranger':'shade';entities.push({type:kind,x:p.x,y:p.y,hp:(kind==='warden'?300:kind==='ranger'?55:65)+wave*9,maxHp:(kind==='warden'?300:kind==='ranger'?55:65)+wave*9,speed:(kind==='ranger'?.75:.62)+wave*.025,attack:Math.random(),radius:kind==='warden'?.75:.36,phase:Math.random()*TAU,flash:0,attackFlash:0,burn:0,alive:true});run.spawned++}
function lineOfSight(x1,y1,x2,y2){const d=Math.hypot(x2-x1,y2-y1),steps=Math.ceil(d*9);for(let i=1;i<steps;i++){const t=i/steps;if(isWall(x1+(x2-x1)*t,y1+(y2-y1)*t))return false}return true}
function shoot(){if(state!=='playing'||fireTimer>0)return;fireTimer=run.rate;run.shots++;let target=null,best=.105;for(const e of entities){if(!e.alive)continue;const dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy),diff=Math.abs(normAngle(Math.atan2(dy,dx)-player.angle));const cone=Math.atan2(e.radius*.7,d);if(d<15&&diff<Math.max(best,cone)&&lineOfSight(player.x,player.y,e.x,e.y)){best=diff;target=e}}
 effects.push({type:'muzzle',x:player.x+Math.cos(player.angle)*.7,y:player.y+Math.sin(player.angle)*.7,life:.13,max:.13,angle:player.angle,color:run.cls.color});if(target){const dmg=run.damage*(1+Math.random()*.09);target.hp-=dmg;target.flash=.12;effects.push({type:'impact',x:target.x,y:target.y,life:.22,max:.22,color:run.cls.color});$('hit-marker').style.opacity='1';setTimeout(()=>$('hit-marker').style.opacity='0',75);if(run.cls.id==='ember')target.burn=2.2;if(run.cls.id==='storm'){const near=entities.find(e=>e!==target&&e.alive&&Math.hypot(e.x-target.x,e.y-target.y)<3&&lineOfSight(target.x,target.y,e.x,e.y));if(near){near.hp-=run.damage*.45;near.flash=.12;effects.push({type:'chain',x1:target.x,y1:target.y,x2:near.x,y2:near.y,life:.16,max:.16,color:run.cls.color});if(near.hp<=0)killEnemy(near)}}if(target.hp<=0)killEnemy(target)} }
function killEnemy(e){if(!e.alive)return;e.alive=false;run.kills++;run.waveKills++;run.streak=Math.min(99,run.streak+1);run.bestStreak=Math.max(run.bestStreak,run.streak);run.health=Math.min(run.maxHealth,run.health+run.soulHeal);effects.push({type:'burst',x:e.x,y:e.y,life:.55,max:.55,color:run.cls.color});if(run.waveKills>=run.waveTarget&&run.spawned>=run.waveTarget&&!entities.some(x=>x.alive)){setTimeout(()=>{if(state!=='playing')return;if(run.wave>=run.maxWaves)endRun(true);else openUpgrade()},650)}}
function castAbility(){if(state!=='playing'||abilityTimer>0)return;abilityTimer=10*run.abilityRate;const type=run.cls.ability;const radius=type==='ward'?0:4.2;effects.push({type:'ability',x:player.x,y:player.y,life:.5,max:.5,color:run.cls.color});if(type==='ring'){for(const e of entities){if(e.alive&&Math.hypot(e.x-player.x,e.y-player.y)<radius){e.hp-=run.damage*1.6;e.flash=.2;if(e.hp<=0)killEnemy(e)}}say('CINDER RING · THE FLAME ANSWERS')}
 else if(type==='siphon'){let n=0;for(const e of entities.filter(e=>e.alive).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y)).slice(0,4)){e.hp-=run.damage*1.15;e.flash=.18;n++;effects.push({type:'homing',x:e.x,y:e.y,life:.35,max:.35,color:run.cls.color});if(e.hp<=0)killEnemy(e)}run.health=Math.min(run.maxHealth,run.health+8*n);say('UNSEEN THREAD · VITALITY SIPHONED')}
 else if(type==='ward'){run.ward+=42;for(const e of entities){if(e.alive&&Math.hypot(e.x-player.x,e.y-player.y)<2.4){e.hp-=run.damage*.8;e.attack=1.2;if(e.hp<=0)killEnemy(e)}}say('STONE WARD · THE EARTH HOLDS')}
 else {for(const e of entities.filter(e=>e.alive).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y)).slice(0,5)){e.hp-=run.damage*1.25;e.flash=.2;effects.push({type:'chain',x1:player.x,y1:player.y,x2:e.x,y2:e.y,life:.25,max:.25,color:run.cls.color});if(e.hp<=0)killEnemy(e)}say('SKYFALL · LIGHTNING CASCADES') }}
function dash(){if(state!=='playing'||dashTimer>0)return;dashTimer=1.3;const mx=(keys.KeyD?1:0)-(keys.KeyA?1:0),my=(keys.KeyS?1:0)-(keys.KeyW?1:0);let a=mx||my?player.angle+Math.atan2(my,mx):player.angle;for(let i=0;i<11;i++){const nx=player.x+Math.cos(a)*.18,ny=player.y+Math.sin(a)*.18;if(canStand(nx,ny,.22)){player.x=nx;player.y=ny}}effects.push({type:'dash',x:player.x,y:player.y,life:.35,max:.35,color:run.cls.color})}
function damagePlayer(amount){if(run.ward>0){const blocked=Math.min(amount,run.ward);run.ward-=blocked;amount-=blocked}if(amount<=0)return;run.health-=amount;$('damage-flash').style.opacity='.8';setTimeout(()=>$('damage-flash').style.opacity='0',120);run.streak=1;if(run.health<=0){run.health=0;endRun(false)}}
function updateGame(delta){if(state!=='playing')return;dt=Math.min(delta,.05);run.elapsed=(performance.now()-run.start)/1000;fireTimer=Math.max(0,fireTimer-dt);abilityTimer=Math.max(0,abilityTimer-dt);dashTimer=Math.max(0,dashTimer-dt);spawnTimer-=dt;
 if(run.spawned<run.waveTarget&&spawnTimer<=0){spawnEnemy(run.wave===6&&run.spawned===0);spawnTimer=Math.max(.42,1.35-run.wave*.1)}
 let forward=(keys.KeyW?1:0)-(keys.KeyS?1:0)+(-joystick.y),side=(keys.KeyD?1:0)-(keys.KeyA?1:0)+joystick.x;const len=Math.hypot(forward,side);if(len>1){forward/=len;side/=len}const speed=run.speed*(keys.ShiftLeft||keys.ShiftRight?1.35:1);const vx=(Math.cos(player.angle)*forward-Math.sin(player.angle)*side)*speed*dt,vy=(Math.sin(player.angle)*forward+Math.cos(player.angle)*side)*speed*dt;if(canStand(player.x+vx,player.y,.22))player.x+=vx;if(canStand(player.x,player.y+vy,.22))player.y+=vy;
 if(keys.ArrowLeft)player.angle-=dt*2.2;if(keys.ArrowRight)player.angle+=dt*2.2;if(mouseDown||touchFire)shoot();
 entities.forEach(e=>{if(!e.alive)return;e.phase+=dt*2;if(e.flash>0)e.flash-=dt;if(e.burn>0){e.burn-=dt;if(Math.random()<dt*2)e.hp-=2.2}const dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy);if(e.type==='ranger'){if(d>5){const step=e.speed*dt;e.x+=dx/d*step;e.y+=dy/d*step}else if(d<3.4){e.x-=dx/d*e.speed*dt*.6;e.y-=dy/d*e.speed*dt*.6}e.attack-=dt;if(d<8&&lineOfSight(e.x,e.y,player.x,player.y)&&e.attack<=0){e.attack=2.2;effects.push({type:'enemybolt',x:e.x,y:e.y,targetX:player.x,targetY:player.y,life:.6,max:.6});setTimeout(()=>{if(state==='playing'&&Math.hypot(player.x-e.x,player.y-e.y)<7)damagePlayer(9+run.wave)},550)}}else if(d>e.radius+.55){const step=e.speed*dt;e.x+=dx/d*step;e.y+=dy/d*step}if(d<e.radius+.65){e.attack-=dt;if(e.attack<=0){e.attack=.9;damagePlayer(8+run.wave*1.3)}}if(e.hp<=0)killEnemy(e)});
 entities=entities.filter(e=>e.alive);effects.forEach(e=>e.life-=dt);effects=effects.filter(e=>e.life>0);if(bannerTimer>0){bannerTimer-=dt;if(bannerTimer<=0)$('wave-banner').classList.remove('show')}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}
 if(run.spawned>=run.waveTarget&&run.waveKills>=run.waveTarget&&!entities.length){if(run.wave>=run.maxWaves)endRun(true);else openUpgrade()}updateHud()}

